    Log = apps.get_model('maintenance', 'MaintenanceActivityLog')
    now = timezone.now()
    for interval in Downtime.objects.select_related('record'):
        end = interval.end_at or now
        segments = []
        if interval.record_id:
            logs = list(
                Log.objects.filter(record_id=interval.record_id).exclude(to_status='').order_by('created_at')
            )
            status = 'REPORTED'
            for log in logs:
                if log.created_at <= interval.start_at:
                    status = log.to_status
            cursor, current = interval.start_at, STATUS_TO_CATEGORY.get(status)
            for log in logs:
                if log.created_at <= interval.start_at or log.created_at >= end:
                    continue
                if current:
                    segments.append((current, cursor, log.created_at))
                cursor, current = log.created_at, STATUS_TO_CATEGORY.get(log.to_status)
            if current and cursor < end:
                segments.append((current, cursor, end if interval.end_at else None))
        if not segments:
            segments = [('UNTRACKED', interval.start_at, interval.end_at)]
        Phase.objects.bulk_create([
            Phase(downtime=interval, record_id=interval.record_id, category=category, started_at=start, ended_at=stop)
            for category, start, stop in segments
        ])


